using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        if (Vector512.IsHardwareAccelerated && data.Length >= Vector512<int>.Count)
        {
            IncrementAbove512(data, threshold);
        }
        else if (Vector256.IsHardwareAccelerated && data.Length >= Vector256<int>.Count)
        {
            IncrementAbove256(data, threshold);
        }
        else if (Vector128.IsHardwareAccelerated && data.Length >= Vector128<int>.Count)
        {
            IncrementAbove128(data, threshold);
        }
        else
        {
            ScalarFallback(data, threshold);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void IncrementAbove512(Span<int> data, int threshold)
    {
        ref int start = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector512<int>.Count;
        var vThreshold = Vector512.Create(threshold);

        for (; i <= lastBlockStart; i += Vector512<int>.Count)
        {
            var vec = Vector512.LoadUnsafe(ref start, (nuint)i);
            // GreaterThan mask: -1 for lanes > threshold, 0 otherwise.
            // Subtracting -1 adds 1; subtracting 0 is a no-op.
            vec -= Vector512.GreaterThan(vec, vThreshold);
            vec.StoreUnsafe(ref start, (nuint)i);
        }

        // Handle remaining elements with a final overlapping vector load.
        if (i < data.Length)
        {
            var vec = Vector512.LoadUnsafe(ref start, (nuint)lastBlockStart);
            vec -= Vector512.GreaterThan(vec, vThreshold);
            vec.StoreUnsafe(ref start, (nuint)lastBlockStart);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void IncrementAbove256(Span<int> data, int threshold)
    {
        ref int start = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector256<int>.Count;
        var vThreshold = Vector256.Create(threshold);

        for (; i <= lastBlockStart; i += Vector256<int>.Count)
        {
            var vec = Vector256.LoadUnsafe(ref start, (nuint)i);
            vec -= Vector256.GreaterThan(vec, vThreshold);
            vec.StoreUnsafe(ref start, (nuint)i);
        }

        if (i < data.Length)
        {
            var vec = Vector256.LoadUnsafe(ref start, (nuint)lastBlockStart);
            vec -= Vector256.GreaterThan(vec, vThreshold);
            vec.StoreUnsafe(ref start, (nuint)lastBlockStart);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void IncrementAbove128(Span<int> data, int threshold)
    {
        ref int start = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector128<int>.Count;
        var vThreshold = Vector128.Create(threshold);

        for (; i <= lastBlockStart; i += Vector128<int>.Count)
        {
            var vec = Vector128.LoadUnsafe(ref start, (nuint)i);
            vec -= Vector128.GreaterThan(vec, vThreshold);
            vec.StoreUnsafe(ref start, (nuint)i);
        }

        if (i < data.Length)
        {
            var vec = Vector128.LoadUnsafe(ref start, (nuint)lastBlockStart);
            vec -= Vector128.GreaterThan(vec, vThreshold);
            vec.StoreUnsafe(ref start, (nuint)lastBlockStart);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ScalarFallback(Span<int> data, int threshold)
    {
        for (int i = 0; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

