private static void IncrementAbove128(Span<int> data, int threshold)
{
    ref int start = ref MemoryMarshal.GetReference(data);
    int i = 0;
    int lastBlockStart = data.Length - Vector128<int>.Count;
    var vThreshold = Vector128.Create(threshold);

    for (; i <= lastBlockStart; i += Vector128<int>.Count)
    {
        var vec = Vector128.LoadUnsafe(ref start, (nuint)i);
        vec -= Vector128.GreaterThan(vec, vThreshold);
        vec.StoreUnsafe(ref start, (nuint)i);
    }

    if (i < data.Length)
    {
        var vec = Vector128.LoadUnsafe(ref start, (nuint)lastBlockStart);
        vec -= Vector128.GreaterThan(vec, vThreshold);
        vec.StoreUnsafe(ref start, (nuint)lastBlockStart);
    }
}

toolArgs.new_str:
[MethodImpl(MethodImplOptions.AggressiveInlining)]
private static void IncrementAbove128(Span<int> data, int threshold)
{
    ref int start = ref MemoryMarshal.GetReference(data);
    int i = 0;
    int lastBlockStart = data.Length - Vector128<int>.Count;
    var vThreshold = Vector128.Create(threshold);

    for (; i <= lastBlockStart; i += Vector128<int>.Count)
    {
        var vec = Vector128.LoadUnsafe(ref start, (nuint)i);
        vec -= Vector128.GreaterThan(vec, vThreshold);
        vec.StoreUnsafe(ref start, (nuint)i);
    }

    for (; i < data.Length; i++)
    {
        if (data[i] > threshold)
            data[i]++;
    }
}

